import { useCallback, useEffect, useRef, useState } from 'react';
import { Landmark, Volume2, VolumeX, X } from 'lucide-react';

import ChatMessage from './ChatMessage';
import ChatInput from './ChatInput';
import QuickOptions from './QuickOptions';
import ProgressIndicator from './ProgressIndicator';
import StepFieldCard from './StepFieldCard';
import ApplicationSummary from './ApplicationSummary';
import Button from '../common/Button';

import useChat from '../../hooks/useChat';
import useApplicationSession, {
  SESSION_STAGE,
} from '../../hooks/useApplicationSession';
import useVoiceInput from '../../hooks/useVoiceInput';

import { FIELD_TYPES } from '../../config/applicationSteps';
import { submitApplicationToAWS } from '../../services/awsService';
import { speak, cancelSpeech } from '../../services/voiceService';
import { interpretUserSpeech } from '../../services/geminiService';

export default function AssistantPanel({ onClose }) {
  const { messages, addBotMessage, addUserMessage } = useChat();
  const session = useApplicationSession();

  const bodyRef = useRef(null);
  const lastPromptedStepId = useRef(null);
  const summaryAnnounced = useRef(false);
  const handleFreeTextRef = useRef(null);

  const [submitting, setSubmitting] = useState(false);

  // --- Voice-first additions ---------------------------------------------
  // voiceMode is the hands-free Gemini-style session toggle. When off,
  // everything behaves exactly as it did before this change (push-to-talk
  // mic, no TTS). voiceModeRef mirrors the state for use inside async
  // callbacks (speak() onEnd, etc.) where a stale closure could otherwise
  // read an outdated value.
  const [voiceMode, setVoiceMode] = useState(false);
  const voiceModeRef = useRef(false);

  const [speaking, setSpeaking] = useState(false);
  const [thinking, setThinking] = useState(false);
  const lastSpokenMessageId = useRef(null);

  const {
    stage,
    currentStep,
    currentIndex,
    currentStepNumber,
    totalSteps,
    answers,
    visibleSteps,
    fieldError,
    start,
    submitAnswer,
    goToPrevious,
    editStep,
    markSubmitted,
  } = session;

  const isInProgress = stage === SESSION_STAGE.IN_PROGRESS;
  const isSummary = stage === SESSION_STAGE.SUMMARY;
  const isWelcome = stage === SESSION_STAGE.WELCOME;
  const isSubmitted = stage === SESSION_STAGE.SUBMITTED;

  const isChoice = currentStep?.type === FIELD_TYPES.CHOICE;
  const isFieldCard = [FIELD_TYPES.CURRENCY, FIELD_TYPES.NAME].includes(
    currentStep?.type
  );
  const hasPrevious = currentIndex > 0;

  const handleVoiceResult = useCallback((text) => {
    // Pause listening the instant we have a final transcript, so the
    // recognizer isn't still capturing while we process/respond — it gets
    // restarted automatically once the assistant's reply finishes speaking
    // (see the "speak newest bot message" effect below).
    if (voiceModeRef.current) stopVoiceRef.current?.();
    handleFreeTextRef.current?.(text);
  }, []);

  // continuous/autoRestart are driven directly by voiceMode. When voice
  // mode is off these are false/false, which reproduces the exact original
  // one-shot push-to-talk hook behaviour used by ChatInput's mic button.
  const {
    supported: voiceSupported,
    listening,
    interimTranscript,
    error: voiceError,
    start: startVoice,
    stop: stopVoice,
  } = useVoiceInput({
    onResult: handleVoiceResult,
    continuous: voiceMode,
    autoRestart: voiceMode,
  });

  // startVoice/stopVoice identities change when voiceMode flips (their
  // internal continuous flag changes). Refs let other callbacks always
  // call the current version without needing them in dependency arrays.
  const startVoiceRef = useRef(startVoice);
  const stopVoiceRef = useRef(stopVoice);
  useEffect(() => {
    startVoiceRef.current = startVoice;
    stopVoiceRef.current = stopVoice;
  }, [startVoice, stopVoice]);

  useEffect(() => {
    if (!isInProgress || !currentStep?.id) return;
    if (lastPromptedStepId.current === currentStep.id) return;

    lastPromptedStepId.current = currentStep.id;
    addBotMessage(currentStep.assistantPrompt);
  }, [isInProgress, currentStep, addBotMessage]);

  useEffect(() => {
    if (isSummary && !summaryAnnounced.current) {
      summaryAnnounced.current = true;
      addBotMessage(
        "That's everything I need — here's a summary to check over."
      );
    }

    if (isInProgress) summaryAnnounced.current = false;
  }, [isSummary, isInProgress, addBotMessage]);

  useEffect(() => {
    if (bodyRef.current)
      bodyRef.current.scrollTop = bodyRef.current.scrollHeight;
  }, [messages, stage]);

  // Speaks the newest bot message whenever one appears, as long as voice
  // mode is on. This single effect covers both the initial "greeting"
  // (turning voice mode on resets lastSpokenMessageId, so whatever bot
  // message is already on screen gets read aloud) and every subsequent
  // reply, without duplicating logic between the two cases.
  useEffect(() => {
    if (!voiceMode) return;

    const lastBotMessage = [...messages].reverse().find((m) => m.sender === 'bot');
    if (!lastBotMessage) return;
    if (lastSpokenMessageId.current === lastBotMessage.id) return;

    lastSpokenMessageId.current = lastBotMessage.id;
    stopVoiceRef.current?.();
    setThinking(false);
    setSpeaking(true);

    speak(lastBotMessage.text, {
      onEnd: () => {
        setSpeaking(false);
        if (voiceModeRef.current) startVoiceRef.current?.();
      },
      onError: () => {
        setSpeaking(false);
      },
    });
  }, [messages, voiceMode]);

  useEffect(() => {
    // Stop any speech in flight if the panel unmounts (e.g. user closes it
    // mid-response).
    return () => cancelSpeech();
  }, []);

  const commitAnswer = (value, label) => {
    addUserMessage(label);

    const result = submitAnswer(value);
    if (!result.valid) addBotMessage(result.error);
  };

  const handleQuickOptionSelect = (value) => {
    const option = currentStep?.options?.find((o) => o.value === value);
    commitAnswer(value, option?.label ?? value);
  };

  const handleFieldCardSubmit = (value) => {
    const label =
      currentStep.type === FIELD_TYPES.CURRENCY
        ? `$${value}`
        : `${value.firstName ?? ''} ${value.lastName ?? ''}`.trim();

    commitAnswer(value, label || '(no answer)');
  };

  // Only reached when the deterministic choice-matching in handleFreeText
  // below has already failed AND we're in voice mode — this is the one
  // and only path that calls the Gemini backend. The final answer still
  // goes through submitAnswer(), so useApplicationSession stays the single
  // source of truth for what gets recorded; Gemini only helps interpret
  // ambiguous natural speech into one of the step's existing valid options.
  const resolveChoiceWithGemini = async (text) => {
    setThinking(true);

    try {
      const context = {
        currentStepId: currentStep.id,
        stepType: currentStep.type,
        options: currentStep.options?.map((o) => ({
          label: o.label,
          value: o.value,
        })),
        stage,
      };

      console.log('[AI] Gemini context payload:', context);

      const result = await interpretUserSpeech(text, context);
      console.log('[Gemini] Parsed intent:', result?.intent, '| value:', result?.value, '| reply:', result?.reply);

      const option = currentStep.options?.find((o) => o.value === result?.value);
      console.log('[AI] Matching against currentStep.options:', currentStep.options, '→ matched option:', option);

      if (result?.intent === 'answer' && option) {
        console.log('[Application] Submitting answer:', option.value);
        const submitResult = submitAnswer(option.value);
        if (!submitResult.valid) {
          console.warn('[Application] submitAnswer rejected value:', submitResult.error);
          addBotMessage(submitResult.error);
        } else if (result.reply) {
          addBotMessage(result.reply);
        }
        return;
      }

      console.warn('[Gemini] No confident option match. Raw result:', result);
      addBotMessage(
        result?.reply ||
          "Sorry, I didn't quite catch that — please choose one of the options above, or try rephrasing."
      );
    } catch (err) {
      console.error('[Gemini] Request failed:', err);
      console.warn('[Gemini] Falling back to manual input');
      addBotMessage(
        "Sorry, I'm having a little trouble understanding right now — please choose one of the options above, or try rephrasing."
      );
    } finally {
      setThinking(false);
    }
  };

  const handleFreeText = (text) => {
    if (!currentStep) return;

    if (currentStep.type === FIELD_TYPES.CHOICE) {
      const normalized = text.trim().toLowerCase();

      const match = currentStep.options.find(({ label, value }) => {
        const optionLabel = label.toLowerCase();
        const optionValue = value.toLowerCase();

        return (
          optionLabel === normalized ||
          optionValue === normalized ||
          optionLabel.includes(normalized) ||
          normalized.includes(optionLabel.split(' ')[0])
        );
      });

      addUserMessage(text);

      if (!match) {
        console.log('[AI] Local matcher: no confident match for:', text);
        console.log('[AI] voiceMode is', voiceModeRef.current ? 'ON — calling Gemini fallback' : 'OFF — skipping Gemini');

        if (voiceModeRef.current) {
          resolveChoiceWithGemini(text);
        } else {
          addBotMessage(
            "Sorry, I didn't quite catch that — please choose one of the options above, or try rephrasing."
          );
        }
        return;
      }

      const result = submitAnswer(match.value);
      if (!result.valid) addBotMessage(result.error);
      return;
    }

    if (currentStep.type === FIELD_TYPES.NAME) {
      const parts = text.trim().split(/\s+/);

      if (parts.length < 2) {
        addUserMessage(text);
        addBotMessage('Could you give me both your first and last name?');
        return;
      }

      const [firstName, ...lastName] = parts;

      commitAnswer(
        { firstName, lastName: lastName.join(' ') },
        text
      );
      return;
    }

    commitAnswer(text, text);
  };

  handleFreeTextRef.current = handleFreeText;

  const handleSubmitApplication = async () => {
    setSubmitting(true);

    try {
      await submitApplicationToAWS(answers);
      markSubmitted();
    } catch {
      addBotMessage(
        "I'm having trouble submitting right now. You can try again, or continue using the form manually."
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleVoiceStart = () => {
    if (!voiceSupported) return;

    // Barge-in: tapping the mic while the assistant is speaking cancels
    // the utterance and starts listening immediately.
    if (speaking) {
      cancelSpeech();
      setSpeaking(false);
      startVoice();
      return;
    }

    listening ? stopVoice() : startVoice();
  };

  const handleVoiceModeToggle = () => {
    setVoiceMode((prev) => {
      const next = !prev;
      voiceModeRef.current = next;

      if (next) {
        // Force the "speak newest message" effect to treat whatever's
        // currently on screen as new, so it reads it aloud as the greeting.
        lastSpokenMessageId.current = null;
      } else {
        cancelSpeech();
        stopVoice();
        setSpeaking(false);
        setThinking(false);
      }

      return next;
    });
  };

  const handleClose = () => {
    cancelSpeech();
    stopVoice();
    onClose?.();
  };

  const assistantState = voiceError
    ? 'error'
    : thinking
      ? 'thinking'
      : speaking
        ? 'speaking'
        : listening
          ? 'listening'
          : 'idle';

  const voiceStatusLabel = {
    listening: 'Listening…',
    thinking: 'Thinking…',
    speaking: 'Speaking…',
    error: voiceError || 'Something went wrong',
    idle: 'Voice mode on',
  }[assistantState];

  return (
    <div
      className="rl-panel"
      role="dialog"
      aria-label="Responsive Lending AI Loan Assistant"
      aria-modal="false"
    >
      <header className="rl-panel__header">
        <div className="rl-panel__header-left">
          <span className="rl-panel__avatar" aria-hidden="true">
            <Landmark size={18} strokeWidth={2.3} />
          </span>

          <div className="rl-panel__titles">
            <div className="rl-panel__title">Responsive Lending</div>
            <div className="rl-panel__subtitle">AI Loan Assistant</div>
          </div>
        </div>

        <div className="rl-panel__header-right">
          <button
            type="button"
            className={`rl-panel__voice-toggle ${
              voiceMode ? 'rl-panel__voice-toggle--active' : ''
            }`}
            onClick={handleVoiceModeToggle}
            disabled={!voiceSupported}
            aria-pressed={voiceMode}
            aria-label={voiceMode ? 'Turn off voice mode' : 'Turn on voice mode'}
            title={
              voiceSupported
                ? voiceMode
                  ? 'Voice mode on — tap to turn off'
                  : 'Turn on hands-free voice mode'
                : 'Voice not supported in this browser'
            }
          >
            {voiceMode ? (
              <Volume2 size={16} strokeWidth={2.3} />
            ) : (
              <VolumeX size={16} strokeWidth={2.3} />
            )}
          </button>

          <button
            type="button"
            className="rl-panel__close"
            onClick={handleClose}
            aria-label="Close chat"
          >
            <X size={16} strokeWidth={2.4} />
          </button>
        </div>
      </header>

     {voiceMode && (
        <div
          className={`rl-voice-status rl-voice-status--${assistantState}`}
          aria-live="polite"
        >
          <span className="rl-voice-status__indicator" aria-hidden="true">
            {assistantState === 'listening' && (
              <span className="rl-waveform">
                <span /><span /><span /><span /><span />
              </span>
            )}
            {assistantState === 'thinking' && (
              <span className="rl-thinking-dots">
                <span /><span /><span />
              </span>
            )}
            {assistantState === 'speaking' && (
              <Volume2 size={14} strokeWidth={2.3} />
            )}
            {assistantState === 'error' && (
              <AlertCircle size={14} strokeWidth={2.3} />
            )}
          </span>

          <span className="rl-voice-status__text">
            {assistantState === 'listening' && interimTranscript
              ? `"${interimTranscript}"`
              : voiceStatusLabel}
          </span>
        </div>
      )}
      {isInProgress && (
        <ProgressIndicator
          current={currentStepNumber}
          total={totalSteps}
        />
      )}

      <div
        className="rl-panel__body"
        ref={bodyRef}
        aria-live="polite"
      >
        {isWelcome && (
          <div className="rl-welcome">
            <div className="rl-welcome__header">
              <span className="rl-welcome__avatar" aria-hidden="true">
                <Landmark size={16} strokeWidth={2.3} />
              </span>

              <span className="rl-welcome__name">
                Responsive Lending Assistant
              </span>
            </div>

            <p className="rl-welcome__text">
              Hi! I'm here to help you complete your loan application.
              We can do this together, step by step.
            </p>

            <Button variant="primary" block onClick={start}>
              Start Application
            </Button>
          </div>
        )}

        {messages.map(({ id, sender, text }) => (
          <ChatMessage key={id} sender={sender} text={text} />
        ))}

        {isInProgress && isChoice && (
          <>
            <QuickOptions
              options={currentStep.options}
              onSelect={handleQuickOptionSelect}
            />

            {hasPrevious && (
              <div
                className="rl-quick-options"
                style={{ paddingLeft: 34 }}
              >
                <button
                  type="button"
                  className="rl-summary__edit-link"
                  onClick={goToPrevious}
                >
                  ← Previous question
                </button>
              </div>
            )}
          </>
        )}

        {isInProgress && isFieldCard && (
          <StepFieldCard
            step={currentStep}
            error={fieldError}
            onSubmit={handleFieldCardSubmit}
            onBack={goToPrevious}
            showBack={hasPrevious}
          />
        )}

        {isSummary && (
          <ApplicationSummary
            steps={visibleSteps}
            answers={answers}
            onEdit={editStep}
            onContinue={handleSubmitApplication}
          />
        )}

        {isSubmitted && (
          <div className="rl-submitted">
            <div className="rl-submitted__icon" aria-hidden="true">
              ✓
            </div>

            <h3 className="rl-submitted__title">
              Application submitted
            </h3>

            <p className="rl-submitted__text">
              Thanks — we've received your details. One of our lending
              specialists will be in touch shortly to discuss your options.
            </p>
          </div>
        )}

        {submitting && (
          <div className="rl-system-note">
            Submitting your application…
          </div>
        )}
      </div>

      {isInProgress && (
        <ChatInput
          onSend={handleFreeText}
          onVoiceStart={handleVoiceStart}
          voiceSupported={voiceSupported}
          listening={listening}
          voiceState={assistantState}
          interimTranscript={interimTranscript}
          voiceError={voiceError}
          disabled={submitting}
          placeholder={listening ? 'Listening…' : 'Type your answer…'}
        />
      )}
    </div>
  );
}
